// Java 8+ con interface funcional
import java.util.function.Function;
Function<Integer, Integer> x = a -> a + 10;
System.out.println(x.apply(5));  // 15

import java.util.function.BiFunction;
BiFunction<Integer, Integer, Integer> sumar = (a, b) -> a + b;
System.out.println(sumar.apply(5, 3));  // 8

import java.util.function.Function;

static Function<Integer, Integer> hacerDoble(int n) {
    return a -> a * n;
}
// En main:
Function<Integer, Integer> doblar = hacerDoble(2);
System.out.println(doblar.apply(11));  // 22
